{
  "name": "sdio_core_config_3",
  "confidence": "medium",
  "docstring": "Configures an SDIO/GPIO peripheral block and an auxiliary register block, starts the hardware operation, waits for a ready/status bit, reads a counter value, and returns a scaled float derived from that counter.",
  "subsystem": "hal",
  "var_renames": {
    "v0": "sdio_reg_base",
    "v1": "aux_reg_base",
    "v2": "cfg_value_a",
    "v3": "cfg_value_b",
    "v4": "cfg_value_c",
    "v5": "counter_value"
  },
  "struct_hints": [
    {
      "offset": 0,
      "meaning": "control/reset register: zeroed at entry"
    },
    {
      "offset": 1,
      "meaning": "start/trigger register: written with 1 after configuration"
    },
    {
      "offset": 2,
      "meaning": "configuration register with masked bitfield update; bit 25 is set"
    },
    {
      "offset": 3,
      "meaning": "configuration register programmed from global configuration values"
    },
    {
      "offset": 4,
      "meaning": "counter/status register read for return value calculation"
    },
    {
      "offset": 7,
      "meaning": "ready/status register polled and then written for acknowledgment"
    },
    {
      "offset": 14,
      "meaning": "auxiliary register programmed with 296"
    }
  ]
}
